// src/pages/UserDashboard/UserDashboardPage.jsx
import { useState, useEffect, useRef } from "react";
import { useAuth } from "../../context/AuthContext";
import { useToast } from "../../context/ToastContext";
import { getProfile, changePassword, uploadAvatar, getFavorites, getSaved, removeFavorite, removeSaved } from "../../services/userService";
import { FALLBACK_COVER } from "../../utils/mockData";
import Navbar from "../../components/Navbar/Navbar";
import "../../styles/components.css";
import styles from "./UserDashboardPage.module.css";

export default function UserDashboardPage() {
  const { user, updateCurrentUser } = useAuth();
  const showToast = useToast();
  const fileRef   = useRef();

  const [favorites, setFavorites] = useState([]);
  const [saved, setSaved]         = useState([]);
  const [loadingData, setLoadingData] = useState(true);
  const [pwdForm, setPwdForm]     = useState({ current:"", newP:"", confirm:"" });
  const [pwdError, setPwdError]   = useState("");
  const [pwdSuccess, setPwdSuccess] = useState("");

  useEffect(() => {
    Promise.all([getFavorites(), getSaved()])
      .then(([fRes, sRes]) => {
        setFavorites(fRes.data.favorites);
        setSaved(sRes.data.saved);
      })
      .catch(() => {})
      .finally(() => setLoadingData(false));
  }, []);

  async function handleChangePwd(e) {
    e.preventDefault();
    setPwdError(""); setPwdSuccess("");
    if (pwdForm.newP.length < 8) { setPwdError("Password must be at least 8 characters"); return; }
    if (pwdForm.newP !== pwdForm.confirm) { setPwdError("Confirmation does not match"); return; }
    try {
      await changePassword(pwdForm);
      setPwdSuccess(" Password changed successfully");
      setPwdForm({ current:"", newP:"", confirm:"" });
    } catch(err) {
      setPwdError(err.response?.data?.message || "Current password is incorrect");
    }
  }

  async function handleAvatarFile(e) {
    const f = e.target.files?.[0];
    if (!f) return;
    try {
      const res = await uploadAvatar(f);
      updateCurrentUser({ avatar: res.data.avatar_url });
      showToast(" Photo uploaded successfully!");
    } catch { showToast(" Failed to upload the image"); }
  }

  async function handleRemoveFav(id) {
    await removeFavorite(id);
    setFavorites((p) => p.filter((b) => b.id !== id));
    showToast(" Removed from favorites");
  }

  async function handleRemoveSaved(id) {
    await removeSaved(id);
    setSaved((p) => p.filter((b) => b.id !== id));
    showToast(" Removed from saved");
  }

  return (
    <>
      <Navbar searchValue="" onSearchChange={() => {}} />
      <main className={styles.main}>
        {/* Profile */}
        <section className={styles.profileCard}>
          <div className={styles.avatarWrap}>
            {user?.avatar
              ? <img src={user.avatar} className={styles.avatar} alt="avatar" />
              : <div className={styles.avatarPlaceholder}>{user?.name?.[0]?.toUpperCase()}</div>}
            <button className={styles.avatarEdit} onClick={() => fileRef.current?.click()} title="Change Image"></button>
            <input ref={fileRef} type="file" accept="image/*" style={{display:"none"}} onChange={handleAvatarFile} />
          </div>
          <div className={styles.profileInfo}>
            <h2 className={styles.profileName}>{user?.name}</h2>
            <p className={styles.profileMeta}>@{user?.username}</p>
            <p className={styles.profileMeta}> {user?.email}</p>
            <div className={styles.profileStats}>
              <span> {favorites.length} Favorites</span>
              <span> {saved.length} Saved</span>
            </div>
          </div>
        </section>

        {/* Favorites */}
        <section className={styles.section}>
          <h3 className={styles.sectionTitle}>Favorites books</h3>
          {loadingData ? <div className="empty-state">loading ...</div>
          : favorites.length === 0 ? <div className="empty-state">You haven't added any books to your favorites yet</div>
          : <div className={styles.booksList}>
              {favorites.map((book) => (
                <div key={book.id} className={styles.bookItem}>
                  <img src={book.cover} alt={book.title} className={styles.bookCover} onError={(e)=>{e.target.src=FALLBACK_COVER(book.title)}} />
                  <button className={styles.removeBtn} onClick={() => handleRemoveFav(book.id)}>✕</button>
                  <p className={styles.bookTitle}>{book.title}</p>
                </div>
              ))}
            </div>}
        </section>

        {/* Saved */}
        <section className={styles.section}>
          <h3 className={styles.sectionTitle}> Saved books</h3>
          {loadingData ? <div className="empty-state">loading ...</div>
          : saved.length === 0 ? <div className="empty-state">You haven't saved any books yet</div>
          : <div className={styles.booksList}>
              {saved.map((book) => (
                <div key={book.id} className={styles.bookItem}>
                  <img src={book.cover} alt={book.title} className={styles.bookCover} onError={(e)=>{e.target.src=FALLBACK_COVER(book.title)}} />
                  <button className={styles.removeBtn} onClick={() => handleRemoveSaved(book.id)}>✕</button>
                  <p className={styles.bookTitle}>{book.title}</p>
                </div>
              ))}
            </div>}
        </section>

        {/* Change Password */}
        <section className={styles.section}>
          <h3 className={styles.sectionTitle}> Change Password</h3>
          {pwdError   && <div className="alert alert-error">{pwdError}</div>}
          {pwdSuccess && <div className="alert alert-success">{pwdSuccess}</div>}
          <form onSubmit={handleChangePwd} className={styles.pwdForm}>
            <input className="form-input" type="password" placeholder="Current Password" value={pwdForm.current} onChange={(e)=>setPwdForm({...pwdForm,current:e.target.value})} />
            <input className="form-input" type="password" placeholder="New Password" value={pwdForm.newP} onChange={(e)=>setPwdForm({...pwdForm,newP:e.target.value})} />
            <input className="form-input" type="password" placeholder="Confirm New Password" value={pwdForm.confirm} onChange={(e)=>setPwdForm({...pwdForm,confirm:e.target.value})} />
            <button type="submit" className="btn btn-primary" style={{width:"fit-content"}}>Change Password</button>
          </form>
        </section>
      </main>
    </>
  );
}
